	"point_4_summary_1": "\u0646\u0642\u062F \u062C\u0639\u0644\u06CC \u0628\u0646\u0627\u06CC\u0627 \u062C\u0627 \u0633\u06A9\u062A\u0627 \u06C1\u06D2 \u0627\u0648\u0631 \u062C\u0639\u0644\u06CC \u0646\u0648\u0679\u0648\u06BA \u06A9\u0627 \u067E\u062A\u06C1 \u0644\u06AF\u0627\u0646\u0627 \u0627\u06A9\u062B\u0631 \u0645\u0634\u06A9\u0644 \u06C1\u0648\u062A\u0627 \u06C1\u06D2\u06D4 Bitcoin \u06A9\u0631\u067E\u0679\u0648\u06AF\u0631\u0627\u0641\u06A9 \u062B\u0628\u0648\u062A \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u06A9\u0631\u062A\u0627 \u06C1\u06D2 \u062C\u0648 \u062C\u0639\u0644\u0633\u0627\u0632\u06CC \u06A9\u0648 \u0631\u06CC\u0627\u0636\u06CC\u0627\u062A\u06CC \u0637\u0648\u0631 \u067E\u0631 \u0646\u0627\u0645\u0645\u06A9\u0646 \u0628\u0646\u0627\u062A\u0627 \u06C1\u06D2\u06D4",
	"point_5_summary_1": "\u0646\u0642\u062F \u062D\u06A9\u0648\u0645\u062A\u0648\u06BA \u062C\u0627\u0631\u06CC \u06A9\u0631\u062A\u06CC \u06C1\u06CC\u06BA \u0627\u0648\u0631 \u06A9\u0646\u0679\u0631\u0648\u0644 \u06A9\u0631\u062A\u06CC \u06C1\u06CC\u06BA\u060C \u062C\u0648 \u062C\u062A\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06BA \u0686\u06BE\u0627\u067E \u0633\u06A9\u062A\u06CC \u06C1\u06CC\u06BA\u06D4 Bitcoin \u063A\u06CC\u0631 \u0645\u0631\u06A9\u0632\u06CC \u0646\u06CC\u0679\u0648\u0631\u06A9 \u067E\u0631 \u06A9\u0627\u0645 \u06A9\u0631\u062A\u0627 \u06C1\u06D2 \u062C\u06C1\u0627\u06BA \u06A9\u0633\u06CC \u0627\u06CC\u06A9 \u0627\u062B\u0627\u0631\u062A \u06A9\u0627 \u06A9\u0646\u0679\u0631\u0648\u0644 \u0646\u06C1\u06CC\u06BA\u06D4",
	"point_6_summary_1": "\u0646\u0642\u062F \u062C\u0633\u0645\u0627\u0646\u06CC \u0637\u0648\u0631 \u067E\u0631 \u0631\u06A9\u06BE\u0646\u0627 \u0636\u0631\u0648\u0631\u06CC \u06C1\u06D2\u060C \u062C\u0648 \u0627\u0633\u06D2 \u0686\u0648\u0631\u06CC\u060C \u06AF\u0645 \u06C1\u0648\u0646\u06D2\u060C \u0622\u06AF \u06CC\u0627 \u0636\u0628\u0637\u06CC \u06A9\u0627 \u0646\u0634\u0627\u0646\u06C1 \u0628\u0646\u0627\u062A\u0627 \u06C1\u06D2\u06D4",
	"point_6_summary_2": "\u0644\u06CC\u06A9\u0646 Bitcoin \u06A9\u0648 \u062E\u0648\u062F \u062D\u0641\u0627\u0638\u062A \u0645\u06CC\u06BA \u0645\u062D\u0641\u0648\u0638 \u0637\u0631\u06CC\u0642\u06D2 \u0633\u06D2 \u0631\u06A9\u06BE\u0627 \u062C\u0627 \u0633\u06A9\u062A\u0627 \u06C1\u06D2",
	"point_6_summary_3": "\u0633\u0645\u0627\u0631\u0679 \u0641\u0648\u0646 \u0627\u06CC\u067E \u06CC\u0627 \u0645\u062E\u0635\u0648\u0635 \u0648\u0627\u0644\u0679 \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u06A9\u0631 \u06A9\u06D2\u060C \u062C\u0648 \u0622\u067E \u06A9\u0648 \u062C\u0633\u0645\u0627\u0646\u06CC \u0630\u062E\u06CC\u0631\u06D2 \u06A9\u06D2 \u062E\u0637\u0631\u0627\u062A \u06A9\u06D2 \u0628\u063A\u06CC\u0631 \u0627\u067E\u0646\u06D2 \u067E\u06CC\u0633\u0648\u06BA \u067E\u0631 \u0645\u06A9\u0645\u0644 \u06A9\u0646\u0679\u0631\u0648\u0644 \u062F\u06CC\u062A\u0627 \u06C1\u06D2\u06D4",
	"point_7_summary_1": "\u0646\u0642\u062F \u06A9\u06CC \u06A9\u0645 \u0627\u0632 \u06A9\u0645 \u0627\u06A9\u0627\u0626\u06CC\u0627\u06BA \u06C1\u0648\u062A\u06CC \u06C1\u06CC\u06BA - \u0622\u067E \u067E\u06CC\u0633\u06D2 \u06A9\u0648 \u0627\u0633 \u0633\u06D2 \u0686\u06BE\u0648\u0679\u06D2 \u062D\u0635\u0648\u06BA \u0645\u06CC\u06BA \u062A\u0642\u0633\u06CC\u0645 \u0646\u06C1\u06CC\u06BA \u06A9\u0631 \u0633\u06A9\u062A\u06D2\u06D4 Bitcoin \u06A9\u0648 100 \u0645\u0644\u06CC\u0646 \u0686\u06BE\u0648\u0679\u06CC \u0627\u06A9\u0627\u0626\u06CC\u0648\u06BA \u0645\u06CC\u06BA \u062A\u0642\u0633\u06CC\u0645 \u06A9\u06CC\u0627 \u062C\u0627 \u0633\u06A9\u062A\u0627 \u06C1\u06D2 \u062C\u0646\u06C1\u06CC\u06BA satoshis \u06A9\u06C1\u062A\u06D2 \u06C1\u06CC\u06BA\u06D4"
